// Joins all Supabase migrations into one file, so setup is a single paste + Run in the SQL Editor.
// Run after adding or changing a migration: node scripts/build-supabase-setup.mjs
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';

export const HEADER = `-- Full Supabase setup for a NEW project: all migrations in order, generated by scripts/build-supabase-setup.mjs.
-- Supabase dashboard -> SQL Editor -> New query -> paste this whole file -> Run.
-- Do not edit by hand; edit supabase/migrations/ and regenerate.
`;

export function buildSetup(dir = 'supabase/migrations') {
  const files = readdirSync(dir).filter((f) => f.endsWith('.sql')).sort();
  return HEADER + files.map((f) => `\n-- ===== ${f} =====\n${readFileSync(`${dir}/${f}`, 'utf8')}`).join('');
}

if (import.meta.url === `file://${process.argv[1]}`) {
  writeFileSync('supabase/setup_all.sql', buildSetup());
  console.log('wrote supabase/setup_all.sql');
}
